  stk asegs m lo (bv_unsigned sp) ->
  rw_cells asegs m 0x797ee8 (atexit_cells2 fin p1 p2 2 0x797f00 0 0x207434 0x207434) ->
  rw_cells asegs m 0x798008 [C8 (Z_to_bv 64 0xe9284); C8 (Z_to_bv 64 0xf9f40)] ->
  rw_cells asegs m 0x777114 [C1 (Z_to_bv 8 0)] ->
